    def command(self, command, timeout):
        argv = shlex.split(command)
        if not argv:
            raise ValueError("empty command")
        rules = self.profile.get("tools", [])
        allowed = "Bash" in rules or any(rule == "Bash(%s:*)" % argv[0] for rule in rules)
