        # still gets no credential: only this minimal environment.
        with tempfile.TemporaryDirectory(prefix="role-command-") as scratch:
            env = {"PATH": os.environ["PATH"], "HOME": scratch, "LANG": "C.UTF-8", "CI": "true",
